    "consulta.steps.title": "¿Cómo funciona?",
    "consulta.steps.subtitle": "Cuatro pasos para recibir atención: primero la solicitud, luego el registro en Doctor8.",
    "consulta.step1.title": "Complete la solicitud",
    "consulta.step1.text": "Complete el <strong>formulario de solicitud</strong> en el sitio de ACURA BRASIL con sus datos, síntomas y necesidades. Recibirá un número de protocolo.",
    "consulta.step1.btn": "Completar solicitud",
