    "consulta.powered": "Plataforma <a href=\"https://app.doctor8.org\" target=\"_blank\" rel=\"noopener\">Doctor8</a> · Proyecto <a href=\"sos-venezuela.html\">SOS Salud Venezuela</a> · ACURA BRASIL",
    "consulta.pt.title": "Cómo funciona",
    "consulta.pt.intro": "Para pacientes y familiares en Venezuela — o brasileños apoyando familiares en el país — el flujo es el mismo:",
