    "consulta.badge": "Gratuito · Telemedicina · 24h conforme disponibilidade",
    "consulta.hero.title": "Consulta médica e psicológica online",
    "consulta.hero.subtitle": "Atendimento gratuito para vítimas dos terremotos na Venezuela, organizado pela ACURA BRASIL através da plataforma Doctor8.",
    "consulta.hero.btn.start": "Iniciar consulta agora →",
    "consulta.hero.btn.login": "Já tenho conta",
    "consulta.hero.note": "A plataforma detecta automaticamente o idioma do seu navegador.",
    "consulta.steps.title": "Como funciona?",
    "consulta.steps.subtitle": "Quatro passos para receber atendimento: primeiro a solicitação, depois o cadastro no Doctor8.",
    "consulta.step1.title": "Complete a solicitação",
    "consulta.step1.text": "Preencha o <strong>formulário de solicitação</strong> no site da ACURA BRASIL com seus dados, sintomas e necessidades. Você receberá um número de protocolo.",
    "consulta.step1.btn": "Completar solicitação",
